from __future__ import annotations
from .canonical import digest_object,stable_id

def build_handoff(*,migration_id:str,upstream_digest:str,package_registry_digest:str,parity_registry_digest:str,treatment_seed_digest:str,blocked_ids:list[str],ready_ids:list[str])->dict:
    body={"schema_version":"1.0.0","handoff_type":"LCM09B_TO_LCM10A","handoff_id":stable_id("LCM09BHANDOFF",migration_id,package_registry_digest,parity_registry_digest),"phase_id":"LCM-09B","master_phase":"LCM-09","migration_id":migration_id,"upstream_handoff_digest":upstream_digest,"package_registry_digest":package_registry_digest,"parity_registry_digest":parity_registry_digest,"treatment_dependency_seed_digest":treatment_seed_digest,"reference_ready_setup_ids":sorted(ready_ids),"explicitly_blocked_setup_ids":sorted(blocked_ids),"completed_gates":["PORTFOLIO_ACCOUNTING","CANONICAL_REFERENCE_PACKAGE_MATERIALIZATION","FAIL_CLOSED_FACTORY_BINDING","BLOCKER_PRESERVATION","PARITY_DISPOSITION_ACCOUNTING","TREATMENT_DEPENDENCY_SEED","AUTHORITY_NEGATIVE_CLOSURE"],"failed_dimensions":[],"blocked_dimensions":["LEGACY_BEHAVIORAL_PARITY_FOR_BLOCKED_IDENTITIES","CANONICAL_CONTEXT_BINDING_FOR_BLOCKED_IDENTITIES","TREATMENT_IMPLEMENTATION_PENDING_LCM10"],"unknown_dimensions":["SEMANTIC_EQUIVALENCE_FOR_PROVISIONAL_IDENTITIES","OWNER_APPROVAL_FOR_PROVISIONAL_IDENTITIES"],"allowed_next_actions":["INVENTORY_TREATMENT_AND_EXECUTION_CAPABILITIES","PRESERVE_SETUP_BLOCKERS","BIND_TREATMENT_DEPENDENCIES_WITHOUT_EXECUTION_AUTHORITY"],"forbidden_actions":["ORDER_ROUTING","CAPITAL_ACTIVATION","PROMOTION_AUTHORITY","BROAD_CONSUMER_CUTOVER","SOURCE_MOVE_OR_DELETE","INFER_SETUP_SEMANTICS_FROM_STATIC_EVIDENCE"],"consumer_cutover_allowed":False,"promotion_authority_created":False,"runtime_authority_created":False,"live_order_authority_created":False,"capital_authority_created":False,"claim_ceiling":"LCM_09B_REFERENCE_ONLY"}
    return {**body,"handoff_digest":digest_object(body)}
